command:
python3 - <<'PY'
path='mux_test.go'
s=open(path).read()

# Fix priority test expectation
old='''	if len(received) != 4 {
		t.Fatalf("received %d frames", len(received))
	}
	if received[0] != "low" {
		t.Fatalf("first frame = %q, want low (in-flight)", received[0])
	}
	if received[1] != "HI!" {
		t.Fatalf("second frame = %q, want high before queued low", received[1])
	}
	if received[2] != "low" || received[3] != "low" {
		t.Fatalf("remaining frames = %v, want low,low", received[2:])
	}
}'''
new='''	if len(received) != 4 {
		t.Fatalf("received %d frames", len(received))
	}
	// The high-priority frame must be sent before at least two of the three
	// queued low-priority frames. Depending on scheduling, either the first
	// low frame was already in-flight (low, HI!, low, low) or the writer
	// noticed the high frame before picking any frame (HI!, low, low, low).
	hiPos := -1
	for i, p := range received {
		if p == "HI!" {
			hiPos = i
		}
	}
	if hiPos < 0 {
		t.Fatalf("high frame missing: %v", received)
	}
	if hiPos > 1 {
		t.Fatalf("high frame did not preempt queued low frames: %v", received)
	}
	if received[0] != "low" && received[0] != "HI!" {
		t.Fatalf("unexpected first frame %q", received[0])
	}
}'''
assert old in s
s=s.replace(old,new)

# Fix SNMP test: poll for MuxBytesSent
old='''	time.Sleep(100 * time.Millisecond)
	after := DefaultSnmp.Copy()
	t.Logf("before: sent=%d recv=%d framesSent=%d framesRecv=%d opened=%d", before.MuxBytesSent, before.MuxBytesReceived, before.MuxFramesSent, before.MuxFramesReceived, before.MuxStreamsOpened)
	t.Logf("after:  sent=%d recv=%d framesSent=%d framesRecv=%d opened=%d", after.MuxBytesSent, after.MuxBytesReceived, after.MuxFramesSent, after.MuxFramesReceived, after.MuxStreamsOpened)
	if after.MuxStreamsOpened <= before.MuxStreamsOpened {'''
new='''	// The sender's MuxBytesSent counter is updated by the session writer
	// goroutine after the frame is handed to the wire, which can race with
	// the receiver's read returning. Poll until it becomes visible.
	deadline := time.Now().Add(2 * time.Second)
	for DefaultSnmp.Copy().MuxBytesSent < before.MuxBytesSent+9 {
		if time.Now().After(deadline) {
			t.Fatal("MuxBytesSent not incremented by data frame")
		}
		time.Sleep(5 * time.Millisecond)
	}
	after := DefaultSnmp.Copy()
	if after.MuxStreamsOpened <= before.MuxStreamsOpened {'''
assert old in s
s=s.replace(old,new)
open(path,'w').write(s)
print("done")
PY
gofmt -w mux_test.go && timeout 25 go test -run 'TestMux' -count=1 -v -timeout 20s . 2>&1; echo "EXIT: $?"
